import{_ as n,l as i,o as t,c as s,v as e,p as h,x as r,d as l,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Knuth TAOCP","description":"","frontmatter":{"title":"Knuth TAOCP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/knuth-taocp.md","filePath":"cs/knuth-taocp.md","lastUpdated":1789023840000}'),d={name:"cs/knuth-taocp.md"};function u(A,a,m,E,_,T){const o=i("Mermaid");return t(),s("div",null,[a[1]||(a[1]=e('<h1 id="knuth-taocp" tabindex="-1">Knuth TAOCP <a class="header-anchor" href="#knuth-taocp" aria-label="Permalink to &quot;Knuth TAOCP&quot;">​</a></h1><div class="epigraph"><p>把算法写成可分析的对象：正确性、MIX 上的步数、最坏与平均；卷册是分析的仓库，不是课序本身。</p><footer>—— Knuth, The Art of Computer Programming（多卷，自 1968 年起）</footer></div><p><a href="/cs/shannon-1948-paper">上一课</a>附录对照了通信数学。附录对照，不插入主干。主干已在<a href="/cs/shannon-1948-paper">循环不变式</a>、<a href="/cs/asymptotic-notation">渐近记号</a>、<a href="/cs/divide-conquer">分治</a>、排序与查找各课用过「先写对、再计数」；这里对照 <strong>TAOCP 的问题</strong>：把具体算法写成可被数学分析的文本，并用 MIX/MMIX 当同一台假想机。不把七卷目录抄进课序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CLRS 与本栏算法课已经给了主定理与排序下界。Knuth 的缺口是工程与分析同一本书：随机数据下的平均、精确到指令的 MIX 计数、以及把离散对象的生成函数当工具。主干不采用 MIX 当 ISA 课——<a href="/cs/riscv-int-isa">RISC-V</a> 才是组成课的指令。附录只对照「算法值得分析到常数与分布」这一立场。</p><p><span class="marginnote">第一卷基础、第三卷排序与查找，是主干引用最多的部分。不要把未完成卷的传闻当文献。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对每一个算法：不变式或归纳、然后在假想机上计数。平均分析假设输入分布。这与主干「渐近为主、常数留给实现」互补：TAOCP 更愿意把 \\(A\\) 与 \\(B\\) 算到项。B 树、哈希、堆，主干数据结构课已经用外存与局部性改写过 Knutt 式分析的对象。</p>',8)),(t(),h(c,null,{default:r(()=>[p(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ALG%5B%22%E7%AE%97%E6%B3%95%E6%96%87%E6%9C%AC%22%5D%20--%3E%20COR%5B%22%E6%AD%A3%E7%A1%AE%E6%80%A7%22%5D%0A%20%20ALG%20--%3E%20MIX%5B%22%E5%81%87%E6%83%B3%E6%9C%BA%E8%AE%A1%E6%95%B0%22%5D%0A%20%20ALG%20--%3E%20AVG%5B%22%E5%B9%B3%E5%9D%87%20%2F%20%E5%88%86%E5%B8%83%22%5D%0A%20%20ALG%20--%3E%20TRUNK%5B%22%E4%B8%BB%E5%B9%B2%3A%20%E6%B8%90%E8%BF%91%E4%B8%8E%E4%B8%8D%E5%8F%98%E5%BC%8F%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>假想机让「一步」有定义，避免高级语言隐藏分配。主干组成课用真实 ISA 做同一件事，对象换成流水线与 Cache。TAOCP 不处理并发与分布式，那些是 Dijkstra、Lamport 附录。本附录不把文学编程当课序要求。</p><h3 id="为何对照而不插入主干" tabindex="-1">为何对照而不插入主干 <a class="header-anchor" href="#为何对照而不插入主干" aria-label="Permalink to &quot;为何对照而不插入主干&quot;">​</a></h3><p>若按 TAOCP 卷序上课，本栏会在排序里停年。主干按知识树：结构 → 算法 → 编译 → 系统。Knuth 是分析风格的对照，不是「排序课应改用 MIX」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 TAOCP 与 CLRS 争「正统教材」。下一篇对照 Dijkstra 1965 如何把互斥写成进程合作，那是 OS 同步课已经取用的观念。</p><p>组合生成与精确计数在 TAOCP 很重，主干<a href="/cs/counting-combinatorics">组合计数</a>只取够用的一层，不按卷册展开。</p><p>对照结束应回到主干算法与数据结构课的渐近与不变式，而不是改用 MIX 当组成课 ISA。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 Knuth TAOCP：算法可被正确性加计数双重分析。</li><li>主干用渐近与 RISC-V，不插入 MIX 课序。</li><li>并发不是这套卷册的中心，见 Dijkstra 附录。</li><li>出处：Knuth, <em>The Art of Computer Programming</em>。</li></ul>',10))])}const B=n(d,[["render",u]]);export{f as __pageData,B as default};
